package net.civeira.phylax.feature.observe.observedslo.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.event.ObservedSloEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedSloEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedSloEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedSlo entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
